# A2 Key (KET): sınav ve çalışma bölümü
# Biçim: Reading & Writing (okuma 5 bölüm + yazma 2 görev), Listening 5 bölüm, Speaking 2 bölüm
I_R1='Her kısa metni oku ve metnin ne söylediğini en iyi anlatan seçeneği bul.'
I_R2='Üç metni oku. Her soru için doğru kişiyi (A, B ya da C) seç. Bir kişi birden fazla kez seçilebilir.'
I_R3='Metni oku ve soruları cevapla.'
I_R4='Metni oku ve her boşluk için doğru kelimeyi seç.'
I_R5='Metni oku ve her boşluğa TEK kelime yaz.'
I_L1='Beş kısa konuşma dinleyeceksin. Her soru için doğru cevabı seç.'
I_L2='Bir kayıt dinleyeceksin. Her boşluğa bir kelime, sayı ya da tarih yaz.'
I_L3='İki kişinin konuşmasını dinle ve soruları cevapla.'
I_L4='Beş kısa kayıt dinleyeceksin. Her soru için doğru cevabı seç.'
I_L5='Bir konuşma dinleyeceksin. Her kişiyi doğru seçenekle (A–H) eşleştir. Üç seçenek fazladır.'
N={'R1':'Okuma 1 · Kısa metinler','R2':'Okuma 2 · Kişi eşleştirme','R3':'Okuma 3 · Uzun metin','R4':'Okuma 4 · Çoktan seçmeli boşluk','R5':'Okuma 5 · Açık boşluk',
   'L1':'Dinleme 1 · Kısa konuşmalar','L2':'Dinleme 2 · Not tamamlama','L3':'Dinleme 3 · Uzun konuşma','L4':'Dinleme 4 · Kısa kayıtlar','L5':'Dinleme 5 · Eşleştirme'}
def P(k,**o):
    d={'k':k,'nm':N[k],'ti':('Reading' if k[0]=='R' else 'Listening')+' Part '+k[1],'ins':{'R1':I_R1,'R2':I_R2,'R3':I_R3,'R4':I_R4,'R5':I_R5,'L1':I_L1,'L2':I_L2,'L3':I_L3,'L4':I_L4,'L5':I_L5}[k]}
    d.update(o);return d
def q(x,qq,o,a,tg,e,**k):
    d={'q':qq,'o':o,'a':a,'tg':tg,'e':e}
    if x:d['x']=x
    d.update(k);return d
def lq(i,sc,qq,o,a,tg,e):return {'id':i,'sc':sc,'q':qq,'o':o,'a':a,'tg':tg,'e':e}
W_PTS=lambda *a:[(x,y) for x,y in a]

